"""Compatibility helpers for tokenizer checkpoints across transformers versions."""

from __future__ import annotations

import json
from pathlib import Path

from transformers import AutoTokenizer


_TOKENIZER_ARTIFACTS = (
    "tokenizer.json",
    "tokenizer.model",
    "vocab.json",
    "merges.txt",
    "spiece.model",
)


def normalize_checkpoint_tokenizer_config(checkpoint_dir: str | Path) -> bool:
    """Normalize tokenizer_config.json in-place when older saves use a stale schema.

    Some tokenizer saves serialize ``extra_special_tokens`` as a list, while newer
    Transformers builds expect a dict. We preserve any listed tokens by merging them
    into ``additional_special_tokens`` and rewrite ``extra_special_tokens`` to an
    empty dict so both HF and vLLM can load the checkpoint directory.
    """

    checkpoint_dir = Path(checkpoint_dir)
    config_path = checkpoint_dir / "tokenizer_config.json"
    if not config_path.exists():
        return False

    with open(config_path) as f:
        config = json.load(f)

    extra_special_tokens = config.get("extra_special_tokens")
    if not isinstance(extra_special_tokens, list):
        return False

    additional_special_tokens = config.get("additional_special_tokens")
    merged_special_tokens = []
    seen = set()

    if isinstance(additional_special_tokens, list):
        for token in additional_special_tokens:
            if isinstance(token, str) and token not in seen:
                merged_special_tokens.append(token)
                seen.add(token)

    for token in extra_special_tokens:
        if isinstance(token, str) and token not in seen:
            merged_special_tokens.append(token)
            seen.add(token)

    config["extra_special_tokens"] = {}
    if merged_special_tokens:
        config["additional_special_tokens"] = merged_special_tokens

    with open(config_path, "w") as f:
        json.dump(config, f, indent=2, sort_keys=True)
        f.write("\n")

    return True


def checkpoint_has_local_tokenizer_artifacts(checkpoint_dir: str | Path) -> bool:
    """Return whether the checkpoint directory contains tokenizer files."""

    checkpoint_dir = Path(checkpoint_dir)
    return any((checkpoint_dir / name).exists() for name in _TOKENIZER_ARTIFACTS)


def resolve_tokenizer_source(checkpoint_dir: str | Path, fallback_model_name: str | None = None):
    """Choose the best tokenizer source for a checkpoint.

    Old checkpoints may contain a partial or stale tokenizer save. When no local
    tokenizer artifacts exist, we fall back to the base model tokenizer.
    """

    checkpoint_dir = Path(checkpoint_dir)
    if checkpoint_has_local_tokenizer_artifacts(checkpoint_dir):
        return checkpoint_dir
    return fallback_model_name or checkpoint_dir


def load_checkpoint_tokenizer(checkpoint_dir: str | Path, fallback_model_name: str | None = None, **kwargs):
    """Load a tokenizer after normalizing known checkpoint compatibility issues."""

    normalize_checkpoint_tokenizer_config(checkpoint_dir)
    if "trust_remote_code" not in kwargs:
        kwargs["trust_remote_code"] = True
    source = resolve_tokenizer_source(checkpoint_dir, fallback_model_name)
    try:
        return AutoTokenizer.from_pretrained(source, **kwargs)
    except Exception:
        if source == checkpoint_dir and fallback_model_name is not None:
            return AutoTokenizer.from_pretrained(fallback_model_name, **kwargs)
        raise

"""Utility functions for ReFT: position computation, injection, save/load, and vLLM integration."""

from __future__ import annotations

import re
from pathlib import Path
from types import MethodType
from typing import Union

import torch
import torch.nn as nn

from .layer import IntervenableLayer


def compute_intervention_locations(position, prompt_lengths, seq_lengths=None):
    """Compute intervention locations from prompt lengths.

    Args:
        position: "first", "last", "prefill", or "all"
        prompt_lengths: int, list of ints, or tensor of prompt lengths per example
        seq_lengths: optional total sequence lengths (for clamping)

    Returns:
        int, list of ints, or tensor of intervention positions.
    """
    if position == "all":
        if isinstance(prompt_lengths, torch.Tensor):
            return torch.full_like(prompt_lengths, -1)
        elif isinstance(prompt_lengths, list):
            return [-1] * len(prompt_lengths)
        return -1

    if position == "first":
        if isinstance(prompt_lengths, torch.Tensor):
            return torch.zeros_like(prompt_lengths)
        elif isinstance(prompt_lengths, list):
            return [0] * len(prompt_lengths)
        return 0

    # position == "last" or "prefill"
    if isinstance(prompt_lengths, torch.Tensor):
        locs = prompt_lengths - 1
        if seq_lengths is not None:
            locs = torch.clamp(locs, max=seq_lengths - 1)
        return locs.long()
    elif isinstance(prompt_lengths, list):
        if seq_lengths is not None:
            return [min(p - 1, s - 1) for p, s in zip(prompt_lengths, seq_lengths)]
        return [p - 1 for p in prompt_lengths]
    else:
        if seq_lengths is not None:
            return min(prompt_lengths - 1, seq_lengths - 1)
        return prompt_lengths - 1


# ---------------------------------------------------------------------------
# Standalone injection (non-PreftModel path)
# ---------------------------------------------------------------------------

def inject_intervenable_layers(model, config):
    """Inject ReFT intervenable layers into a model (in-place).

    This is the standalone injection function for use without the ``PreftModel``
    wrapper.  It mutates the model directly and returns it.

    Accepts either a ``PreftConfig`` or legacy ``InterventionConfig``.
    """
    for param in model.parameters():
        param.requires_grad = False
    if config.hidden_size is None:
        config.hidden_size = model.config.hidden_size

    # Support both PreftConfig (adapter_type) and InterventionConfig (mode)
    adapter_mode = getattr(config, "adapter_type", None) or getattr(config, "mode", "loreft")

    for layer_idx in config.layer_indices:
        if layer_idx >= model.config.num_hidden_layers:
            raise ValueError(
                f"Layer index {layer_idx} exceeds model's num_hidden_layers "
                f"({model.config.num_hidden_layers})"
            )

        original_layer = model.model.layers[layer_idx]

        intervenable_layer = IntervenableLayer(
            original_layer,
            layer_idx,
            config.hidden_size,
            low_rank_dim=config.low_rank_dim,
            position=config.position,
            frozen=config.frozen,
            logging=config.logging,
            mode=adapter_mode,
        )
        model.model.layers[layer_idx] = intervenable_layer

    def _trl_prepare_model_inputs_for_logprob_computation(self, model_inputs, *, attention_mask, logits_to_keep):
        prepared_inputs = dict(model_inputs)
        prompt_mask = attention_mask[:, :-logits_to_keep] if logits_to_keep > 0 else attention_mask
        prepared_inputs["prompt_mask"] = prompt_mask
        return prepared_inputs

    intervention_roots = [model]
    inner_model = getattr(model, "model", None)
    # NOTE: intentionally do NOT register on inner_model. The outer hook
    # already walks model.model.layers and sets layer._intervention_locations;
    # a second hook on the inner root would fire after the outer had popped
    # intervention_locations from kwargs, fall back to attention_mask, and
    # overwrite the correct value with the last non-pad token index.

    def _stash_locations_hook(module, args, kwargs):
        intervention_locations = kwargs.pop("intervention_locations", None)
        prompt_mask = kwargs.pop("prompt_mask", None)
        if intervention_locations is None:
            if prompt_mask is None:
                prompt_mask = getattr(module, "_prompt_mask", None)
                if prompt_mask is None:
                    prompt_mask = kwargs.get("attention_mask", None)
                else:
                    module._prompt_mask = None
            elif inner_model is not None and module is model and inner_model is not model:
                inner_model._prompt_mask = prompt_mask
            if prompt_mask is not None:
                if config.position in ("last", "prefill"):
                    positions = torch.arange(prompt_mask.size(1), device=prompt_mask.device).unsqueeze(0)
                    intervention_locations = (positions * prompt_mask.long()).max(dim=1).values
                elif config.position == "first":
                    intervention_locations = prompt_mask.long().argmax(dim=1)
                else:
                    intervention_locations = None
        input_ids = kwargs.get("input_ids", args[0] if len(args) > 0 else None)
        for layer in model.model.layers:
            if isinstance(layer, IntervenableLayer):
                layer._intervention_locations = intervention_locations
                layer.adapter._input_ids = input_ids
        return args, kwargs

    for root in intervention_roots:
        root.register_forward_pre_hook(_stash_locations_hook, with_kwargs=True)
        root._intervention_config = config
        root._trl_prepare_model_inputs_for_logprob_computation = MethodType(
            _trl_prepare_model_inputs_for_logprob_computation,
            root,
        )
    return model


# ---------------------------------------------------------------------------
# Save / Load adapter weights
# ---------------------------------------------------------------------------

def save_intervention_weights(model, path: Union[str, Path]):
    """Save adapter weights to a safetensors file."""
    try:
        from safetensors.torch import save_file
    except ImportError:
        raise ImportError("safetensors required: pip install safetensors") from None

    path = Path(path)
    if path.suffix != ".safetensors":
        path = path.with_suffix(".safetensors")

    state_dict = {}
    layers = model.model.layers

    for layer_idx, layer in enumerate(layers):
        if isinstance(layer, IntervenableLayer):
            for k, v in layer.adapter.state_dict().items():
                state_dict[f"layer_{layer_idx}.block.{k}"] = v.contiguous()

    if not state_dict:
        raise ValueError("No intervenable layers found in model")

    path.parent.mkdir(parents=True, exist_ok=True)
    save_file(state_dict, str(path))
    print(f"Saved {len(state_dict)} tensors to {path}")


def load_intervention_weights(model, path: Union[str, Path]):
    """Load adapter weights from a safetensors file."""
    try:
        from safetensors.torch import load_file
    except ImportError:
        raise ImportError("safetensors required: pip install safetensors") from None

    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(f"Weights file not found: {path}")

    full_state_dict = load_file(str(path))
    layers = model.model.layers
    loaded_count = 0

    for layer_idx, layer in enumerate(layers):
        if isinstance(layer, IntervenableLayer):
            prefix = f"layer_{layer_idx}.block."
            sub_sd = {k[len(prefix):]: v for k, v in full_state_dict.items() if k.startswith(prefix)}
            if sub_sd:
                layer.adapter.load_state_dict(sub_sd, strict=True)
                loaded_count += 1

    print(f"Loaded adapters for {loaded_count} layers from {path}")
    return model


# ---------------------------------------------------------------------------
# vLLM integration
# ---------------------------------------------------------------------------

def reft_named_parameters_for_vllm(model) -> list[tuple[str, torch.Tensor]]:
    """Return all model weights remapped to the names expected by vLLM.

    IntervenableLayer wraps the original decoder layer as ``.layer`` and
    exposes the adapter as a sibling ``.adapter``.  This gives HF names like::

      layers.N.adapter.X              -> layers.N.reft_adapter.X
      layers.N.layer.self_attn.attn.X -> layers.N.self_attn.X
      layers.N.layer.X                -> layers.N.X
    """
    remapped = []
    for name, param in model.named_parameters():
        vllm_name = re.sub(r"(layers\.\d+)\.adapter\.", r"\1.reft_adapter.", name)
        vllm_name = re.sub(r"(layers\.\d+)\.layer\.self_attn\.attn\.", r"\1.self_attn.", vllm_name)
        vllm_name = re.sub(r"(layers\.\d+)\.layer\.", r"\1.", vllm_name)
        remapped.append((vllm_name, param))
    return remapped


def export_vllm_reft_spec(model) -> dict:
    """Return the ReFT construction spec expected by the forked vLLM API.

    Exports a per-layer adapter map so that each vLLM decoder layer gets a
    deep-copy of the correct HF adapter (with the right ``base`` buffer
    for the orthogonal parametrization).

    """
    config = getattr(model, "_intervention_config", None)
    if config is None:
        config = getattr(model, "preft_config", None)
    if config is None:
        raise ValueError("Model does not have a preft configuration attached.")

    layers = getattr(getattr(model, "model", None), "layers", [])
    adapters: dict[int, nn.Module] = {}
    for idx in config.layer_indices:
        if idx >= len(layers):
            continue
        layer = layers[idx]
        if isinstance(layer, IntervenableLayer):
            adapters[idx] = layer.adapter

    if not adapters:
        raise RuntimeError(
            f"No residual-stream adapter found in intervened layers {config.layer_indices}. "
            "vLLM ReFT construction currently expects an IntervenableLayer adapter."
        )

    first_adapter = next(iter(adapters.values()))
    return {
        "layer_indices": config.layer_indices,
        "position": config.position,
        "sample_adapter": first_adapter,
        "adapters": adapters,
    }

"""Reward and answer parsing helpers."""

from __future__ import annotations

import re
from typing import Optional

from rl_training.code_exec import score_humaneval, score_mbpp

# math-verify: sympy-based equivalence check used by open-r1 / TRL examples.
# Handles \dfrac vs \frac vs decimal vs n/m, units, set/interval equivalence.
# https://github.com/huggingface/Math-Verify
try:
    from math_verify import (
        ExprExtractionConfig,
        LatexExtractionConfig,
        parse as _mv_parse,
        verify as _mv_verify,
    )
    _MATH_VERIFY_AVAILABLE = True
except ImportError:
    _MATH_VERIFY_AVAILABLE = False

_CODE_FENCE_RE = re.compile(r"```(?:python)?\s*(.*?)```", re.DOTALL)
_BEGIN_DONE_RE = re.compile(r"\[BEGIN\](.*?)\[DONE\]", re.DOTALL)


def _legacy_string_match(prediction: str, ground_truth: str) -> bool:
    """Pre-math_verify equality check: strip $/comma/space, compare strings,
    fall back to numeric compare with 1e-3 tolerance. Used as a fallback when
    math_verify can't anchor on the model's free-form output."""
    if prediction is None or ground_truth is None:
        return False
    pred = str(prediction).strip().lower()
    gt = str(ground_truth).strip().lower()
    pred = pred.replace(",", "").replace("$", "").replace(" ", "")
    gt = gt.replace(",", "").replace("$", "").replace(" ", "")
    if pred == gt:
        return True
    try:
        return abs(float(pred) - float(gt)) < 1e-3
    except (ValueError, TypeError):
        return False


def _math_verify_check(prediction: str, ground_truth: str) -> bool:
    """Equivalence check for MATH using HuggingFace math_verify.

    Accepts the *raw model completion* as ``prediction`` so math_verify can
    pull out the last ``\\boxed{...}`` (or fall back to the last expression).
    Wraps a bare-LaTeX gold in ``$...$`` so atom-level expressions like
    ``\\dfrac{1}{2}`` parse without surrounding math-mode delimiters.
    """
    if not _MATH_VERIFY_AVAILABLE or prediction is None or ground_truth is None:
        return False
    gt = ground_truth.strip()
    # If gold is bare LaTeX (no $...$, no \boxed), wrap so math_verify recognises
    # it as a math expression. Pure numbers / words also benefit since the parser
    # then treats them as math atoms.
    if not (gt.startswith("$") or "\\boxed" in gt):
        gt = f"${gt}$"
    try:
        gold_parsed = _mv_parse(gt, extraction_mode="first_match")
        pred_parsed = _mv_parse(
            prediction,
            extraction_config=[
                LatexExtractionConfig(boxed_match_priority=0),
                ExprExtractionConfig(),
            ],
            extraction_mode="first_match",
        )
        return bool(_mv_verify(gold_parsed, pred_parsed))
    except Exception:
        return False


def _extract_code(text: str, dataset_name: str) -> str:
    m = _CODE_FENCE_RE.search(text)
    if m:
        return m.group(1).strip()
    if dataset_name == "mbpp":
        m = _BEGIN_DONE_RE.search(text)
        if m:
            return m.group(1).strip()
    return text.strip()


def extract_answer(text: str, dataset_name: str) -> Optional[str]:
    """Extract the final answer from a model completion."""
    text = text.strip()

    if dataset_name in ("mbpp", "humaneval"):
        return _extract_code(text, dataset_name)

    if dataset_name == "gsm8k":
        if "####" in text:
            answer = text.split("####")[-1].strip()
            match = re.search(r"-?\d+\.?\d*", answer)
            return match.group(0) if match else None

        numbers = re.findall(r"-?\d+\.?\d*", text)
        return numbers[-1] if numbers else None

    if dataset_name == "math":
        # Find the last \boxed{...}, handling nested braces
        idx = text.rfind("\\boxed{")
        if idx >= 0:
            start = idx + len("\\boxed{")
            depth = 1
            i = start
            while i < len(text) and depth > 0:
                if text[i] == "{":
                    depth += 1
                elif text[i] == "}":
                    depth -= 1
                i += 1
            if depth == 0:
                return text[start:i - 1].strip()

        numbers = re.findall(r"-?\d+\.?\d*", text)
        return numbers[-1] if numbers else None

    if dataset_name == "mmlu_pro":
        # Match lm_eval's mmlu_pro task: regex `answer is \(?([A-J])\)?`
        # with the `take_first` filter, case-insensitive.
        m = re.search(r"answer is \(?([A-J])\)?", text, re.IGNORECASE)
        return m.group(1).upper() if m else None

    if dataset_name == "mmlu":
        max_letter = "D"
        # Prefer explicit "answer is X" / "answer: X" patterns (typically last).
        explicit = re.findall(
            rf"(?:answer|option|choice)\s*(?:is|:|=)?\s*\(?\*{{0,2}}([A-{max_letter}])\*{{0,2}}\)?",
            text, re.IGNORECASE,
        )
        if explicit:
            return explicit[-1].upper()
        # Fall back to the last standalone letter token in the response.
        bare = re.findall(rf"(?:^|[^A-Za-z])([A-{max_letter}])(?=[^A-Za-z]|$)", text)
        if bare:
            return bare[-1].upper()
        return None

    return None


def check_answer_correct(prediction: str, ground_truth: str, dataset_name: str,
                         entry_point: str = "", prompt: str = "") -> bool:
    """Check if the predicted answer matches the ground truth."""
    if prediction is None or ground_truth is None:
        return False

    if dataset_name == "mbpp":
        return score_mbpp(prediction, ground_truth)
    if dataset_name == "humaneval":
        # HumanEval scoring needs the full program (signature+docstring+body).
        # `prompt` holds the signature/docstring; `prediction` is body-only.
        # score_humaneval doesn't accept a prompt kwarg, so concat here.
        full_code = (prompt or "") + prediction
        return score_humaneval(full_code, ground_truth, entry_point or "candidate")
    if dataset_name == "math" and _MATH_VERIFY_AVAILABLE:
        # MATH uses \boxed{...} as the canonical final-answer wrapper, which
        # math_verify's LatexExtractionConfig anchors on cleanly. This handles
        # \dfrac vs \frac vs decimal vs n/m / set equivalence. Fall back to
        # legacy string-compare on the extract_answer result if math_verify
        # cannot anchor on the response.
        if _math_verify_check(prediction, ground_truth):
            return True
        legacy_pred = extract_answer(prediction, "math")
        return _legacy_string_match(legacy_pred, ground_truth)
    if dataset_name == "gsm8k":
        # GSM8K's answer convention is `#### N` — math_verify cannot anchor on
        # that and falls through to a whole-text expression scan, which yields
        # large false-positive rates because GSM8K integer golds frequently
        # appear in the question/reasoning by accident. Use the legacy
        # `####`-aware extractor + string match exclusively. This restores
        # parity with the canonical lm-evaluation-harness GSM8K scoring and
        # avoids reward-hacking under RL.
        legacy_pred = extract_answer(prediction, "gsm8k")
        return _legacy_string_match(legacy_pred, ground_truth)
    if dataset_name in ("mmlu", "mmlu_pro"):
        # MMLU's HF dataset returns ground truths as integer indices (0..3 / 0..9);
        # the model emits a letter. Convert digits to the corresponding letter
        # before comparing.
        gt_str = str(ground_truth).strip()
        if gt_str.isdigit():
            idx = int(gt_str)
            if 0 <= idx < 26:
                gt_str = chr(ord("A") + idx)
        return str(prediction).strip().upper() == gt_str.upper()

    pred = str(prediction).strip().lower()
    gt = str(ground_truth).strip().lower()

    pred = pred.replace(",", "").replace("$", "").replace(" ", "")
    gt = gt.replace(",", "").replace("$", "").replace(" ", "")

    if pred == gt:
        return True

    try:
        pred_num = float(pred)
        gt_num = float(gt)
        return abs(pred_num - gt_num) < 1e-3
    except (ValueError, TypeError):
        return False


def compute_reward(completions: list[str], ground_truth: str, dataset_name: str,
                   entry_point: str = "", prompt: str = "") -> list[float]:
    """Return binary rewards for a set of completions."""
    rewards = []

    for completion in completions:
        if dataset_name == "humaneval":
            # Pass the raw completion to score_humaneval. extract_answer's
            # text.strip() destroys the leading indent on body-only
            # completions, so the assembled program (prompt + completion)
            # ends up with `return` at column 0 outside the def.
            predicted = completion
        elif dataset_name == "math" and _MATH_VERIFY_AVAILABLE:
            # MATH: pass the raw completion so math_verify can anchor on
            # \boxed{...}; the legacy fallback in check_answer_correct
            # re-extracts from it if math_verify can't anchor.
            predicted = completion
        elif dataset_name == "gsm8k":
            # GSM8K: pass the raw completion so check_answer_correct can run
            # the `####`-aware extract_answer internally. We deliberately do
            # NOT route GSM8K through math_verify — its whole-text scan
            # false-positives on completions where the gold integer happens
            # to appear in the question / reasoning, which RL exploits as a
            # reward-hacking failure mode.
            predicted = completion
        else:
            predicted = extract_answer(completion, dataset_name)
        correct = check_answer_correct(predicted, ground_truth, dataset_name,
                                       entry_point=entry_point, prompt=prompt)
        rewards.append(1.0 if correct else 0.0)

    return rewards


def make_reward_function(dataset_name: str):
    """Build the GRPO reward callback while preserving the current debug prints."""

    def reward_function(prompts, completions, **kwargs):
        ground_truths = kwargs.get("answer", [])
        # Per-example dataset name (allows training on MBPP, evaluating on
        # HumanEval in the same trainer). Falls back to the bound dataset.
        per_dataset = kwargs.get("_dataset", [dataset_name] * len(completions))
        entry_points = kwargs.get("entry_point", [""] * len(completions))

        if not hasattr(reward_function, "_first_call_done"):
            reward_function._first_call_done = True
            print("\n=== Reward function (first call) ===")
            print(f"Number of completions: {len(completions)}")
            print(f"Number of ground truths: {len(ground_truths)}")
            if completions and ground_truths:
                print("\nExample:")
                print(f"Prompt: {prompts[0][:100]}...")
                print(f"Completion: {completions[0][:300]}...")
                print(f"Ground truth: {ground_truths[0]}")
            print("=" * 40)

        if not ground_truths:
            print("ERROR: No ground truth answers provided!")
            return [0.0] * len(completions)

        rewards = [
            compute_reward([completion], ground_truth, ds, entry_point=ep, prompt=p)[0]
            for completion, ground_truth, ds, ep, p in zip(
                completions, ground_truths, per_dataset, entry_points, prompts
            )
        ]

        if not hasattr(reward_function, "_call_count"):
            reward_function._call_count = 0
        reward_function._call_count += 1

        if reward_function._call_count % 10 == 0:
            mean_reward = sum(rewards) / len(rewards) if rewards else 0.0
            print(f"[Step {reward_function._call_count}] Mean reward: {mean_reward:.3f}")

        return rewards

    return reward_function

"""Logging callbacks used by RL training."""

from __future__ import annotations

import torch
import wandb
from transformers import TrainerCallback


_KNOWN_MODULES = ["q_proj", "v_proj", "k_proj", "o_proj", "gate_proj", "up_proj", "down_proj"]


class LoRALoggingCallback(TrainerCallback):
    """Logs LoRA adapter statistics to wandb each logging step."""

    def __init__(self, model, lora_rank: int, lora_alpha: int, log_svd_every: int = 50):
        self.model = model
        self.scale = lora_alpha / lora_rank
        self.log_svd_every = log_svd_every
        self._cached_grad_norms: dict = {}

    def _parse_lora_params(self):
        """Return dict keyed by (layer_idx, module_type) -> {'A': param, 'B': param}."""
        layers: dict = {}
        for name, param in self.model.named_parameters():
            if "lora_A" not in name and "lora_B" not in name:
                continue
            parts = name.split(".")
            layer_idx = None
            for i, p in enumerate(parts):
                if p == "layers" and i + 1 < len(parts):
                    try:
                        layer_idx = int(parts[i + 1])
                    except ValueError:
                        pass
            module_type = next((m for m in _KNOWN_MODULES if m in name), None)
            if layer_idx is None or module_type is None:
                continue
            key = (layer_idx, module_type)
            layers.setdefault(key, {})
            if "lora_A" in name:
                layers[key]["A"] = param
            else:
                layers[key]["B"] = param
        return layers

    def on_step_end(self, args, state, control, **kwargs):
        """Cache gradient norms before they are zeroed."""
        self._cached_grad_norms = {}
        for (layer_idx, module_type), params in self._parse_lora_params().items():
            A, B = params.get("A"), params.get("B")
            if A is None or B is None:
                continue
            grad_sq = 0.0
            has_grad = False
            for p in (A, B):
                if p.grad is not None:
                    grad_sq += p.grad.float().norm().item() ** 2
                    has_grad = True
            if has_grad:
                self._cached_grad_norms[(layer_idx, module_type)] = grad_sq**0.5

    def on_log(self, args, state, control, logs=None, **kwargs):
        if not args.report_to or "wandb" not in args.report_to:
            return

        step = state.global_step
        metrics: dict = {}
        layers = self._parse_lora_params()

        all_delta_norms, all_A_norms, all_B_norms, all_grad_norms = [], [], [], []
        per_module: dict = {}

        for (layer_idx, module_type), params in layers.items():
            A, B = params.get("A"), params.get("B")
            if A is None or B is None:
                continue

            Af = A.data.float()
            Bf = B.data.float()
            A_norm = Af.norm().item()
            B_norm = Bf.norm().item()
            delta = self.scale * Bf @ Af
            delta_norm = delta.norm().item()

            all_A_norms.append(A_norm)
            all_B_norms.append(B_norm)
            all_delta_norms.append(delta_norm)
            per_module.setdefault(module_type, []).append(delta_norm)

            metrics[f"lora/{module_type}/layer{layer_idx}/A_norm"] = A_norm
            metrics[f"lora/{module_type}/layer{layer_idx}/B_norm"] = B_norm
            metrics[f"lora/{module_type}/layer{layer_idx}/delta_norm"] = delta_norm

            ab_product_bound = A_norm * B_norm
            if ab_product_bound > 0:
                metrics[f"lora/{module_type}/layer{layer_idx}/alignment"] = delta_norm / ab_product_bound

            grad_norm = self._cached_grad_norms.get((layer_idx, module_type))
            if grad_norm is not None:
                all_grad_norms.append(grad_norm)
                metrics[f"lora/{module_type}/layer{layer_idx}/grad_norm"] = grad_norm

            if step % self.log_svd_every == 0 and step > 0:
                try:
                    singular_values = torch.linalg.svdvals(delta)
                    metrics[f"lora/{module_type}/layer{layer_idx}/sv_max"] = singular_values[0].item()
                    metrics[f"lora/{module_type}/layer{layer_idx}/sv_min"] = singular_values[-1].item()
                    stable_rank = (singular_values**2).sum().item() / (
                        singular_values[0] ** 2
                    ).clamp(min=1e-12).item()
                    metrics[f"lora/{module_type}/layer{layer_idx}/stable_rank"] = stable_rank
                except Exception:
                    pass

        def _mean(values):
            return sum(values) / len(values) if values else 0.0

        metrics["lora/summary/delta_norm_mean"] = _mean(all_delta_norms)
        metrics["lora/summary/delta_norm_max"] = max(all_delta_norms) if all_delta_norms else 0.0
        metrics["lora/summary/A_norm_mean"] = _mean(all_A_norms)
        metrics["lora/summary/B_norm_mean"] = _mean(all_B_norms)
        if all_grad_norms:
            metrics["lora/summary/grad_norm_mean"] = _mean(all_grad_norms)
            metrics["lora/summary/grad_norm_max"] = max(all_grad_norms)

        for module_type, norms in per_module.items():
            metrics[f"lora/{module_type}/delta_norm_mean"] = _mean(norms)
            metrics[f"lora/{module_type}/delta_norm_max"] = max(norms)

        wandb.log(metrics)


class ReFTLoggingCallback(TrainerCallback):
    """Logs ReFT adapter statistics to wandb each logging step."""

    def __init__(self, model, log_svd_every: int = 50):
        self.model = model
        self.log_svd_every = log_svd_every
        self._cached_grad_norms: dict = {}
        self._W_init: dict = {}
        self._w2_init: dict = {}
        self._hidden_norm_buf: dict = {}
        self._delta_norm_buf: dict = {}
        self._hook_handles = []
        self._snapshot_init()
        self._register_hooks()

    def _snapshot_init(self):
        for layer_idx, mount, adapter in self._iter_adapters(aggregate_heads=False):
            key = (layer_idx, mount)
            learned_source = getattr(adapter, "learned_source", None)
            if learned_source is not None:
                self._W_init[key] = learned_source.weight.data.float().clone()
            w2 = getattr(adapter, "w2", None)
            if w2 is not None:
                self._w2_init[key] = w2.data.float().clone()

    def _register_hooks(self):
        """Register forward hooks on every adapter to buffer hidden/delta norms."""
        for layer_idx, mount, adapter in self._iter_adapters(aggregate_heads=False):
            key = (layer_idx, mount)

            def make_hook(adapter_key):
                def hook(module, args, output):
                    if not module.training:
                        return
                    hidden = args[0] if isinstance(args, tuple) else args
                    hidden_norm = hidden.detach().float().norm(dim=-1).mean().item()
                    self._hidden_norm_buf.setdefault(adapter_key, []).append(hidden_norm)
                    if isinstance(output, torch.Tensor):
                        delta = output - hidden
                        delta_norm = delta.detach().float().norm(dim=-1).mean().item()
                        self._delta_norm_buf.setdefault(adapter_key, []).append(delta_norm)

                return hook

            handle = adapter.register_forward_hook(make_hook(key))
            self._hook_handles.append(handle)

    def on_train_end(self, args, state, control, **kwargs):
        for handle in self._hook_handles:
            handle.remove()
        self._hook_handles.clear()

    def _iter_adapters(self, aggregate_heads=True):
        """Yield (layer_idx, mount_type, adapter)."""
        from preft import IntervenableLayer

        for layer in self.model.model.layers:
            if not isinstance(layer, IntervenableLayer):
                continue
            yield layer.layer_idx, "block", layer.adapter


    def on_step_end(self, args, state, control, **kwargs):
        """Cache combined gradient norms over all adapter parameters before zero_grad."""
        self._cached_grad_norms = {}
        for layer_idx, mount, adapter in self._iter_adapters(aggregate_heads=False):
            grad_sq = 0.0
            has_grad = False
            for param in adapter.parameters():
                if param.grad is not None:
                    grad_sq += param.grad.float().norm().item() ** 2
                    has_grad = True
            if has_grad:
                self._cached_grad_norms[(layer_idx, mount)] = grad_sq**0.5

    def _get_R(self, adapter):
        """Return (R_float32, orth_metrics_dict) for any adapter with a rotate_layer."""
        rotate = getattr(adapter, "rotate_layer", None)
        if rotate is None:
            return None, {}
        metrics = {}
        rotation = rotate.weight.float()
        metrics["R_norm"] = rotation.norm().item()
        rt_r = rotation.T @ rotation
        orth_err = (rt_r - torch.eye(rt_r.size(0), device=rt_r.device)).norm().item()
        metrics["R_orth_error"] = orth_err
        params = getattr(rotate, "parametrizations", None)
        if params is not None and hasattr(params, "weight"):
            try:
                weight_v = params.weight.original1
                metrics["R_weight_v_norm"] = weight_v.float().norm().item()
            except AttributeError:
                pass
        return rotation, metrics

    def _adapter_metrics(self, layer_idx, mount, adapter, step):
        prefix = f"reft/{mount}/layer{layer_idx}"
        metrics = {}

        rotation, rotation_metrics = self._get_R(adapter)
        for key, value in rotation_metrics.items():
            metrics[f"{prefix}/{key}"] = value

        learned_source = getattr(adapter, "learned_source", None)
        if learned_source is not None:
            weight = learned_source.weight.float()
            metrics[f"{prefix}/W_norm"] = weight.norm().item()
            if learned_source.bias is not None:
                metrics[f"{prefix}/b_norm"] = learned_source.bias.float().norm().item()
            init_key = (layer_idx, mount)
            weight_init = self._W_init.get(init_key)
            if weight_init is not None:
                metrics[f"{prefix}/W_drift"] = (weight - weight_init.to(weight.device)).norm().item()
            if rotation is not None and weight.shape == rotation.T.shape:
                metrics[f"{prefix}/W_minus_Rt_norm"] = (weight - rotation.T).norm().item()
            if step % self.log_svd_every == 0 and step > 0:
                try:
                    singular_values = torch.linalg.svdvals(weight)
                    metrics[f"{prefix}/W_sv_max"] = singular_values[0].item()
                    metrics[f"{prefix}/W_sv_min"] = singular_values[-1].item()
                    metrics[f"{prefix}/W_stable_rank"] = (singular_values**2).sum().item() / (
                        singular_values[0] ** 2
                    ).clamp(min=1e-12).item()
                except Exception:
                    pass

        w2 = getattr(adapter, "w2", None)
        if w2 is not None:
            w2_float = w2.data.float()
            metrics[f"{prefix}/w2_norm"] = w2_float.norm().item()
            init_key = (layer_idx, mount)
            w2_init = self._w2_init.get(init_key)
            if w2_init is not None:
                metrics[f"{prefix}/w2_drift"] = (w2_float - w2_init.to(w2_float.device)).norm().item()
            if step % self.log_svd_every == 0 and step > 0:
                try:
                    singular_values = torch.linalg.svdvals(w2_float)
                    metrics[f"{prefix}/w2_sv_max"] = singular_values[0].item()
                    metrics[f"{prefix}/w2_sv_min"] = singular_values[-1].item()
                    metrics[f"{prefix}/w2_condition"] = (
                        singular_values[0] / singular_values[-1].clamp(min=1e-12)
                    ).item()
                except Exception:
                    pass

        dW = getattr(adapter, "dW", None)
        if dW is not None:
            metrics[f"{prefix}/dW_norm"] = dW.data.float().norm().item()

        bare_bias = getattr(adapter, "bias", None)
        if bare_bias is not None and isinstance(bare_bias, torch.nn.Parameter):
            metrics[f"{prefix}/bias_norm"] = bare_bias.data.float().norm().item()

        gate_down = getattr(adapter, "gate_down", None)
        gate_up = getattr(adapter, "gate_up", None)
        if gate_down is not None:
            metrics[f"{prefix}/gate_down_norm"] = gate_down.weight.data.float().norm().item()
        if gate_up is not None:
            metrics[f"{prefix}/gate_up_norm"] = gate_up.weight.data.float().norm().item()
            if gate_up.bias is not None:
                metrics[f"{prefix}/gate_bias_mean"] = gate_up.bias.data.float().mean().item()
                metrics[f"{prefix}/gate_bias_std"] = gate_up.bias.data.float().std().item()

        grad_norm = self._cached_grad_norms.get((layer_idx, mount))
        if grad_norm is not None:
            metrics[f"{prefix}/grad_norm"] = grad_norm

        return metrics

    def on_log(self, args, state, control, logs=None, **kwargs):
        if not args.report_to or "wandb" not in args.report_to:
            return

        step = state.global_step
        metrics: dict = {}

        all_grad_norms, all_drifts, all_orth_errs = [], [], []
        per_mount_drifts: dict = {}

        for layer_idx, mount, adapter_or_list in self._iter_adapters(aggregate_heads=True):
            if isinstance(adapter_or_list, (list, torch.nn.ModuleList)):
                adapters = list(adapter_or_list)
                head_metrics = [
                    self._adapter_metrics(layer_idx, f"{mount}_head{head_idx}", adapter, step)
                    for head_idx, adapter in enumerate(adapters)
                ]
                prefix = f"reft/{mount}/layer{layer_idx}"

                def _aggregate(key_suffix):
                    values = [
                        head_metric.get(f"reft/{mount}_head{head_idx}/layer{layer_idx}/{key_suffix}")
                        for head_idx, head_metric in enumerate(head_metrics)
                    ]
                    return [value for value in values if value is not None]

                for key_suffix in (
                    "W_norm",
                    "W_drift",
                    "R_orth_error",
                    "grad_norm",
                    "gate_down_norm",
                    "gate_up_norm",
                ):
                    values = _aggregate(key_suffix)
                    if values:
                        metrics[f"{prefix}/{key_suffix}_mean"] = sum(values) / len(values)
                        metrics[f"{prefix}/{key_suffix}_max"] = max(values)
                        if key_suffix == "W_drift":
                            all_drifts.extend(values)
                            per_mount_drifts.setdefault(mount, []).extend(values)
                        elif key_suffix == "R_orth_error":
                            all_orth_errs.extend(values)
                        elif key_suffix == "grad_norm":
                            all_grad_norms.extend(values)
                continue

            adapter = adapter_or_list
            adapter_metrics = self._adapter_metrics(layer_idx, mount, adapter, step)
            metrics.update(adapter_metrics)

            prefix = f"reft/{mount}/layer{layer_idx}"
            drift = adapter_metrics.get(f"{prefix}/W_drift") or adapter_metrics.get(f"{prefix}/w2_drift")
            if drift is not None:
                all_drifts.append(drift)
                per_mount_drifts.setdefault(mount, []).append(drift)
            orth_err = adapter_metrics.get(f"{prefix}/R_orth_error")
            if orth_err is not None:
                all_orth_errs.append(orth_err)
            grad_norm = adapter_metrics.get(f"{prefix}/grad_norm")
            if grad_norm is not None:
                all_grad_norms.append(grad_norm)

        def _mean(values):
            return sum(values) / len(values) if values else 0.0

        if all_drifts:
            metrics["reft/summary/drift_mean"] = _mean(all_drifts)
            metrics["reft/summary/drift_max"] = max(all_drifts)
        if all_orth_errs:
            metrics["reft/summary/R_orth_error_mean"] = _mean(all_orth_errs)
            metrics["reft/summary/R_orth_error_max"] = max(all_orth_errs)
        if all_grad_norms:
            metrics["reft/summary/grad_norm_mean"] = _mean(all_grad_norms)
            metrics["reft/summary/grad_norm_max"] = max(all_grad_norms)
        for mount, drifts in per_mount_drifts.items():
            metrics[f"reft/{mount}/drift_mean"] = _mean(drifts)
            metrics[f"reft/{mount}/drift_max"] = max(drifts)

        all_hidden, all_delta = [], []
        for (layer_idx, mount), values in self._hidden_norm_buf.items():
            if not values:
                continue
            avg = _mean(values)
            metrics[f"reft/{mount}/layer{layer_idx}/hidden_norm"] = avg
            all_hidden.append(avg)
        for key, values in self._delta_norm_buf.items():
            if not values:
                continue
            layer_idx, mount = key
            avg = _mean(values)
            metrics[f"reft/{mount}/layer{layer_idx}/delta_norm"] = avg
            all_delta.append(avg)
            hidden_values = self._hidden_norm_buf.get(key, [])
            if hidden_values:
                metrics[f"reft/{mount}/layer{layer_idx}/delta_rel"] = avg / (_mean(hidden_values) + 1e-8)
        if all_hidden:
            metrics["reft/summary/hidden_norm_mean"] = _mean(all_hidden)
        if all_delta:
            metrics["reft/summary/delta_norm_mean"] = _mean(all_delta)

        self._hidden_norm_buf.clear()
        self._delta_norm_buf.clear()

        wandb.log(metrics)
